_choice_command() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    _argc_util_comp_command
}

_choice_command_args() {
    if [[ "${#argc__positionals[@]}" -lt 2 ]]; then
        _choice_command
    else
        _argc_util_comp_subcommand 0
    fi
}

_choice_git_ref() {
    git for-each-ref --format='%(refname:short)' refs/heads refs/tags refs/remotes 2>/dev/null
}

_choice_hazmat_cd_cmd() {
    if [[ "${#argc__positionals[@]}" -lt 3 ]]; then
        _choice_command
    else
        _argc_util_comp_subcommand 1
    fi
}

_choice_hook() {
    local config
    config="$(_helper_precommit_config)"
    [[ -n "$config" && -f "$config" ]] || return 0
    gawk '
        /^[[:space:]]*-[[:space:]]*id:[[:space:]]*/ {
            value = $0
            sub(/^[[:space:]]*-[[:space:]]*id:[[:space:]]*/, "", value)
            sub(/[[:space:]]+$/, "", value)
            gsub(/^["\047]|["\047]$/, "", value)
            if (value != "") print value
        }
    ' "$config"
}

_choice_repo() {
    local config
    config="$(_helper_precommit_config)"
    [[ -n "$config" && -f "$config" ]] || return 0
    gawk '
        /^[[:space:]]*-[[:space:]]*repo:[[:space:]]*/ {
            value = $0
            sub(/^[[:space:]]*-[[:space:]]*repo:[[:space:]]*/, "", value)
            sub(/[[:space:]]+$/, "", value)
            gsub(/^["\047]|["\047]$/, "", value)
            if (value != "") print value
        }
    ' "$config"
}

_helper_precommit_config() {
    if [[ -n "${argc_config:-}" ]]; then
        printf '%s\n' "$argc_config"
        return 0
    fi
    _argc_util_path_search_parent .pre-commit-config.yaml
}
